async def _landed_change(request: Request, change):
    """The Landed page's buttons: Clear, Clear all and Undo post here through `change` (landed.clear or landed.unclear), which takes the comma-separated landed.key values of the `keys` field. The gates are the For you
    seen route's: signed in to the board (or the board open), from its own origin; the body is capped at 64 KB. A change that changed something republishes the board (debounced; the home Landed count follows with it).
    A form post (no JavaScript) gets a 303 back to the page; the page's own script asks with `Accept: application/json` and gets {"ok": true, "changed": n}, and keeps the line where it is. No keys changes nothing (it is not a clear-everything call)."""
    email = _ui_email(request)
    if not email and not (_ui_open() or _signin._auth_mode() == "off"):
        return PlainTextResponse("sign in to the board", status_code=403)
    if not _answer_same_origin(request):
        return PlainTextResponse("refused: this did not come from the board's own page", status_code=403)
    body = await request.body()
    if len(body) > 65536:
        return PlainTextResponse("refused: the form is too long", status_code=413)
    from urllib.parse import parse_qs
    raw = (parse_qs(body.decode("utf-8", "replace"), keep_blank_values=True).get("keys") or [""])[0]
    keys = [k.strip() for k in raw.split(",") if k.strip()]
    n = change(keys) if keys else 0
    if n:
        _publish()
    if "application/json" in str(request.headers.get("accept") or "").lower():
        return JSONResponse({"ok": True, "changed": n}, headers={"Cache-Control": "no-store"})
    return RedirectResponse("/closed", status_code=303, headers={"Cache-Control": "no-store"})


async def _landed_clear(request: Request):
    """The Landed page's Clear and Clear all buttons: the closes named by `keys` (comma-separated landed.key values: one for a line's Clear, every key the page listed for Clear all) are cleared and leave
    the home count (the page's script keeps their lines in place, dimmed, with an Undo until the page is reloaded)."""
    return await _landed_change(request, _ld.clear)


@mcp.custom_route("/landed/clear", methods=["POST"])
async def landed_clear(request: Request):
    return await _landed_clear(request)


@mcp.custom_route("/landed/unclear", methods=["POST"])
async def landed_unclear(request: Request):
    """The Landed page's Undo: puts back the closes named by `keys` that are cleared and still inside the 60-day window (landed.unclear); an unknown key, an uncleared one or an old one does nothing. Same gates as Clear."""
    return await _landed_change(request, _ld.unclear)


@mcp.custom_route("/landed/seen", methods=["POST"])
async def landed_seen(request: Request):
    """The old Mark all seen route, kept so a Landed page still open from before an earlier change works: it clears the keys it carries, like /landed/clear."""
    return await _landed_clear(request)


def _runners_switch_token(email: str, box: str) -> str:
    """The Disable / Enable form's token on the CI runners page: an HMAC over the signed-in address and the machine, as _watch_token, under its own label."""
    import hashlib, hmac
    return hmac.new(_ui_key(), f"runners-switch\x00{email}\x00{box}".encode(), hashlib.sha256).hexdigest()


def _runners_token_maker(request: Request):
    """The page's token maker for the viewer (None draws no button: no switch script configured, or this copy is read-only)."""
    if _ro.is_read_only() or not _runners.switch_enabled():
        return None
    email = _ui_email(request)
    if not email:
        return None                        # the route needs a real signed-in address, so an open board draws no button that would only be refused
    return lambda box: _runners_switch_token(email, box)


@mcp.custom_route("/runners", methods=["GET"])
async def site_runners(request: Request):
    """The CI runners page: the count cards and each machine's CI runners, idle, running, disabled or offline, with a Disable / Enable button per machine (runners.py).
    Behind the board's sign-in like the other pages; matched before the catch-all below."""
    g = _ui_guard(request)
    if g is not None:
        return g
    from starlette.concurrency import run_in_threadpool
    token = _runners_token_maker(request)

    rmod, _, nmod = _ui_mods()

    def page() -> str:
        return nmod.page_html(rmod.Board(str(_store.STORE)), _runners.serve(), token)     # the last snapshot at once; a rebuild (GitHub and ssh) runs in its own thread
    return HTMLResponse(await run_in_threadpool(page), headers={"Cache-Control": "no-store"})


@mcp.custom_route("/runners.json", methods=["GET"])
async def site_runners_json(request: Request):
    """The CI runners page's data (runners.data): the counts, the runners with their state, job and reason, and the table as HTML, which the page swaps in every 30 s.
    The snapshot behind it is the last one, at once; a viewer finding it older than [runners] cache_s starts the one background rebuild, so many viewers make one set of GitHub calls."""
    g = _ui_guard(request)
    if g is not None:
        return g
    from starlette.concurrency import run_in_threadpool
    token = _runners_token_maker(request)
    nmod = _ui_mods()[2]
    return JSONResponse(await run_in_threadpool(lambda: nmod.data(_runners.serve(), token=token)), headers={"Cache-Control": "no-store"})


@mcp.custom_route("/runners/switch", methods=["POST"])
async def site_runners_switch(request: Request):
    """The CI runners page's Disable / Enable button: turns one machine's CI switch off or on by running the configured switch script (runners.switch_box: argv `bash <switch_script> off|on <box>`, a timeout, one at a time per machine).
    Disable lets a running job finish and then takes no new job. The gates are the other state-changing actions': a read-only copy answers 503 first (the route wrapper), then a real signed-in address (an open board is refused too, as /answer and /watch do), from its own origin,
    the form's token (an HMAC over the viewer and the machine); the body is capped at 4096 bytes; the action and the machine are checked (the machine against runners.switch_boxes: the fleet's names, plus a [runners] boxes entry named in [runners.ssh_hosts]) before anything runs. The page's script asks with
    `Accept: application/json` and gets {"ok": bool, "text": "..."} to show; a form post gets the same text as plain text."""
    email = _ui_email(request)
    if not email:
        return PlainTextResponse("sign in to the board to disable or enable a CI machine", status_code=403)
    if not _answer_same_origin(request):
        return PlainTextResponse("refused: this did not come from the board's own page", status_code=403)
    body = await request.body()
    if len(body) > 4096:
        return PlainTextResponse("refused: the form is too long", status_code=413)
    from urllib.parse import parse_qs
    form = parse_qs(body.decode("utf-8", "replace"), keep_blank_values=True)
    f = lambda k: (form.get(k) or [""])[0]
    box, act = f("box"), f("act")
    import hmac
    if not hmac.compare_digest(f("token").encode(), _runners_switch_token(email, box).encode()):     # bytes: a non-ASCII token is a 403, not a TypeError
        return PlainTextResponse("refused: the form's token does not match; reload the page and send again", status_code=403)
    if act not in _runners.SWITCH_ACTIONS:
        return PlainTextResponse("refused: the action is Disable or Enable", status_code=400)
    if box not in _runners.switch_boxes():
        return PlainTextResponse("refused: that is not one of the fleet's machines", status_code=400)
    from starlette.concurrency import run_in_threadpool
    ok, text = await run_in_threadpool(_runners.switch_box, box, act)
    if "application/json" in str(request.headers.get("accept") or "").lower():
        return JSONResponse({"ok": ok, "text": text}, status_code=200 if ok else 502, headers={"Cache-Control": "no-store"})
    return PlainTextResponse(text, status_code=200 if ok else 502, headers={"Cache-Control": "no-store"})


@mcp.custom_route("/routing/{key:path}", methods=["GET"])
async def site_routing(request: Request):
    """The old address of a details page (/routing/<key>.html): a permanent redirect to /<key>, query
    dropped. It serves nothing itself, so it answers before the sign-in; a path that is not a page key is a plain 404."""
    key = _details_key(str(request.path_params.get("key", "")))
    if not key:
        return PlainTextResponse("not found", status_code=404)
    return RedirectResponse("/" + key, status_code=301)


# The daily board audit: the board's "Audit now" button and its "last audit ran" line. Both sit
# behind the board's own wall, as the board and the item pages do (_ui_guard: the edge's access proxy with [auth] ui_open, the
# server's sign-in without it), and are matched before the catch-all below. The cue itself is audit.cue, shared with the timer.
_AUDIT_METHODS = ["GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"]


@mcp.custom_route("/audit/now", methods=_AUDIT_METHODS)
async def audit_now(request: Request):
    """POST: start the audit now (audit.cue("button")): in [audit] mode "script" a detached `audit.py run`, in mode "agent" a cue to the audit agent; the answer is its
    code with its text: 202 started or cued · 409 a run is in progress · 404 the audit is not enabled · 503 the run could not start (agent mode: the agent is not live). Any other method is 405."""
    g = _ui_guard(request)
    if g is not None:
        return g
    if request.method != "POST":
        return PlainTextResponse("method not allowed: POST /audit/now", status_code=405, headers={"Allow": "POST"})
    from starlette.concurrency import run_in_threadpool
    code, text = await run_in_threadpool(_audit.cue, "button")       # push.py may take seconds: off the event loop
    return PlainTextResponse(text, status_code=code, headers={"Cache-Control": "no-store"})


@mcp.custom_route("/audits", methods=["GET"])
async def audits_page(request: Request):
    """The Audits page: the paces the audits run at, the audit groups with their audits, the latest findings and the recent runs (ui/render.py Board.audits_html, from audit_overview). Behind the board's sign-in,
    drawn on request; its Audit now button posts to /audit/now, like the side panel card's."""
    g = _ui_guard(request)
    if g is not None:
        return g
    from starlette.concurrency import run_in_threadpool

    from stackshot.web.ui import render as r2

    return HTMLResponse(await run_in_threadpool(lambda: r2.Board(str(_store.STORE)).audits_html(runner=_runner_status())), headers={"Cache-Control": "no-store"})


@mcp.custom_route("/audit/status", methods=["GET"])
async def audit_status(request: Request):
    """The audit at a glance (audit.status): enabled, the agent, a run in progress and since when, the last run, the next."""
    g = _ui_guard(request)
    if g is not None:
        return g
    out = _audit.status()
    out["card"] = _audit_overview.card(time.time())      # the side panel card's shortlist: per audit group its audits and its findings in 24 hours (null where the group keeps no findings log)
    out["runner"] = _runner_status()        # the minute set: which mode, and per tick its last run and last error (runner.py)
    out["phase_sweep"] = _phase_sweep_status()      # the stored phase kept true at the clock edges: runs, items swept, stamped, moved, differences seen, last run (_phase_sweep)
    return JSONResponse(out, headers={"Cache-Control": "no-store"})


# The web app manifest, so the board installs as an app window (Chrome "Install page as app"). render.py's _APP_HEAD links it
# with crossorigin="use-credentials" so Chrome's fetch carries the Cloudflare Access cookie; in the server's own sign-in it is
# public like the icons it names: the favicon (<state>/site/favicon.svg, sizes "any") and the PNGs of _APP_ICONS (a launcher
# or splash screen that rasterises the SVG at a small size and scales it up looks soft). theme_color
# is the light theme's --bg token, the background of the board's sticky header; background_color, the splash screen's, is the
# mark's tile colour (#1f1f21), the full-bleed background of every PNG icon, so the splash is the icon's own dark.
# Each icon's src carries its version (render.py icon_href, read at the start), so a new icon is a new URL to the installer;
# the manifest itself is no-cache, so the next fetch sees the new src.
_MANIFEST = {"id": "/", "name": "stackshot", "short_name": "stackshot", "start_url": "/", "scope": "/", "display": "standalone",
             "theme_color": "#fafaf8", "background_color": "#1f1f21",
             "icons": [{"src": _rmod.icon_href("favicon.svg"), "type": "image/svg+xml", "sizes": "any", "purpose": "any"}]
                      + [{"src": _rmod.icon_href(n), "type": "image/png", "sizes": f"{px}x{px}", "purpose": p} for n, (px, p) in _APP_ICONS.items()]}
_IMMUTABLE = {"Cache-Control": "public, max-age=31536000, immutable"}


def _icon_file(request: Request, p: Path, media_type: str) -> FileResponse:
    """An icon from disk. A request whose ?v= is the version of the bytes on disk now (render.py asset_version) may be kept a
    year and never revalidated: that URL can only ever name these bytes. Any other request, the unversioned URL and a stale
    version included, is served exactly as before (no Cache-Control of its own)."""
    v = request.query_params.get("v")
    return FileResponse(str(p), media_type=media_type, headers=_IMMUTABLE if v and v == _rmod.asset_version(p) else None)


def _page_at(request: Request, name: str):
    """The page a path names (`name` is the path with the first slash off): an item's page at items/<gid>, a project's details page at <page key>; None when the
    path names neither. The redirects (items/<gid>.html, items/<gid>/ and an id's old form to its address now, <key>.html and <key>/ to <key>) go to the page."""
    m = _ITEM_PATH.fullmatch(name)
    if m:                                 # /items/<gid>: the item's page; /items/<gid>.html and /items/<gid>/ → 301 to /items/<gid>
        raw = m.group(1)
        gid = _item_gid(raw)              # a temporary id's address → l<n>, /items/<n> → g<n>, an old id → its id now
        if not gid:
            return PlainTextResponse("no such item", status_code=404)
        at = _gh.href_id(gid)             # where the page lives: the id, an issue-numbered one at its number (/items/g<n> redirects to /items/<n>),
                                          # a temporary one at board-tmp-<machine>-<n> (/items/l<n> redirects there)
        if m.group(2) or at != raw:
            return RedirectResponse("/items/" + at, status_code=301)
        return _item_page(request, gid)
    key = _details_key(name)
    if key:                               # /<page key>: the project's details page; /<key>.html and /<key>/ → 301 to /<key>
        if name != key:
            return RedirectResponse("/" + key, status_code=301)
        return _details_page(request, key)
    return None


def _receivers_response():
    """anchor-hub's live receiver checks (receivers.json), read on each request: no render, no git."""
    try:
        ast = json.load(open(_cfg.state("anchor-hub", "status.json"), encoding="utf-8"))
        out = {}
        for k, v in (ast.get("receivers") or {}).items():
            try: ts = int(dt.datetime.strptime(str(v.get("checked", "")), "%Y-%m-%d %H:%M:%S").replace(tzinfo=ZONE).timestamp())
            except Exception: ts = 0
            late = _rh.stale_age(k, bool(v.get("ok")), ts, time.time(), (ast.get("hold") or {}).get(k, 0))      # seconds since a healthy receiver's last check when that is over twice its beat (an announced wait counted out), else 0
            out[k] = {"ok": bool(v.get("ok")), "error": v.get("error"), "checked": v.get("checked", ""), "ts": ts, "type": _rmod.receiver_type(ast, k),
                      "stale": late, "stale_note": _rh.stale_note(k, late) if late else ""}
        return JSONResponse(out, headers={"Cache-Control": "no-store"})
    except Exception:
        return PlainTextResponse("unavailable", status_code=503)


# ----------------------------------------------------------------------------- the board at the root
# The board is drawn by the page renderers in ui/ (ui/render.py, ui/search.py, ui/runners.py), on request, from the store, behind the sign-in. The home is drawn on request and kept for
# _BOARD_HOME_TTL_S, and dropped at once by a publish and by a write from a page of the board.
_BOARD_HOME_LOCK = threading.Lock()         # one render at a time: a burst of requests after a drop makes one
_BOARD_HOME_TTL_S = 30.0
_BOARD_FAIL_BACKOFF_S = 10.0                # after a failed draw no other is tried for this long: the last good copy (or the plain 503) is served meanwhile


def _board_home_draw_locked() -> None:
    """Draw the root home if none is held or the held one is older than _BOARD_HOME_TTL_S, and no draw failed within _BOARD_FAIL_BACKOFF_S. The caller holds _BOARD_HOME_LOCK. Each language has its own
    kept draw (the request's, i18n.current(); English is _BOARD_HOME)."""
    now = time.time()
    slot = _board_home_slot(_i18n.current())
    sig = _i18n.signature()      # a catalog added, removed or edited makes the held draws stale at once (the switch and the words are in them)
    if slot["html"] is not None and now - slot["at"] <= _BOARD_HOME_TTL_S and slot.get("sig") == sig:
        return
    if now - slot["failed"] < _BOARD_FAIL_BACKOFF_S:
        return
    with _BOARD_GEN_LOCK:
        gen = slot["gen"]
    try:
        from stackshot.web.ui import render as r2
        page = r2.Board(str(_store.STORE), contact_of=_contact_label).html()
        slot["drawn"] = int(now)
        slot["sig"] = sig
        slot["html"] = page
        slot["failed"] = 0.0
        with _BOARD_GEN_LOCK:                # a drop between the start of the draw and here is not overwritten: the next read draws again
            slot["at"] = now if slot["gen"] == gen else 0.0
    except Exception as e:  # noqa: BLE001
        slot["failed"] = time.time()  # when it failed, not when it started: a slow failing draw still backs off
        print(f"home render failed: {e.__class__.__name__}: {e}", file=sys.stderr, flush=True)


def _board_home() -> str | None:
    """The root home page as HTML: the kept one while it is younger than _BOARD_HOME_TTL_S, else drawn now; the last good one if a draw fails (and for _BOARD_FAIL_BACKOFF_S after it, with no new draw); None before the first."""
    with _BOARD_HOME_LOCK:
        _board_home_draw_locked()
        return _board_home_slot(_i18n.current())["html"]


def _board_home_kick() -> None:
    """Start one background draw of the root home when none is held or the held one is expired (and no draw failed within _BOARD_FAIL_BACKOFF_S). It never waits: with a draw already running (the
    lock is taken) or nothing to draw it returns at once, so a burst of polls makes at most one thread."""
    if not _BOARD_HOME_LOCK.acquire(blocking=False):
        return
    started = False
    try:
        now = time.time()
        lang = _i18n.current()
        slot = _board_home_slot(lang)
        if (slot["html"] is None or now - slot["at"] > _BOARD_HOME_TTL_S or slot.get("sig") != _i18n.signature()) and now - slot["failed"] >= _BOARD_FAIL_BACKOFF_S:
            def run() -> None:
                try:
                    with _i18n.use(lang):       # a new thread has no request language: the draw is the one asked for
                        _board_home_draw_locked()
                finally:
                    _BOARD_HOME_LOCK.release()
            threading.Thread(target=run, name="home-draw", daemon=True).start()
            started = True
    finally:
        if not started:
            _BOARD_HOME_LOCK.release()


def _board_home_stamp() -> int | None:
    """When the root home the server holds was drawn (epoch seconds): the stamp the page carries, else the time of the draw; None while nothing has been drawn. It only reads: it never draws and
    never waits for a draw, and a drop does not change it (the copy held is the one the stamp tells). Never 0."""
    slot = _board_home_slot(_i18n.current())
    page = slot["html"]
    if page is None:
        return None
    m_ = _STAMP_RE.search(page.encode("utf-8", "replace")[:4096])
    ts = int(m_.group(1)) if m_ else int(slot["drawn"])
    return ts if ts > 0 else None


@mcp.custom_route("/", methods=["GET"])
@mcp.custom_route("/index.html", methods=["GET"])
async def board_home(request: Request):
    """The board: the home drawn by the page renderer (ui/render.py), on request, behind the sign-in."""
    g = _ui_guard(request)
    if g is not None:
        return g
    from starlette.concurrency import run_in_threadpool
    page = await run_in_threadpool(_board_home)
    if page is None:
        return PlainTextResponse("board not rendered yet", status_code=503)
    return HTMLResponse(page, headers={"Cache-Control": "no-store"})


@mcp.custom_route("/render-stamp", methods=["GET"])
async def board_render_stamp(request: Request):
    """{"ts": the draw time of the home the server holds}: its staleness and reachability poll. It never waits for a draw: when the held copy is expired or
    absent it starts one in the background (at most one at a time, not within the back-off after a failure) and answers at once with the stamp held, so an open page sees the new stamp at its next
    poll. With none held it answers 503 JSON (the page's script reads that as unreachable and asks again in 15 s), never a ts of 0."""
    g = _ui_guard(request)
    if g is not None:
        return g
    _board_home_kick()
    ts = _board_home_stamp()
    if ts is None:
        return JSONResponse({"error": "board not rendered yet"}, status_code=503, headers={"Cache-Control": "no-store"})
    return JSONResponse({"ts": ts}, headers={"Cache-Control": "no-store"})


@mcp.custom_route("/{name:path}", methods=["GET"])
async def site_file(request: Request):
    """Static files next to the board (favicon, robots.txt, versions.json), a project's details page at /<page key>
    (projects/x, projects/hub, projects/x/sub), and an item's page at /items/<gid>. Anything else is 404; /mcp, the OAuth, /client, /routing and /audit routes are matched first.
    The page dirs ([pages] dirs: projects/, infra/) are thereby reserved in the site's URL namespace: no static file is served under them."""
    name = request.path_params.get("name", "")
    if name == "healthz":
        if str(request.query_params.get("format") or "").lower() == "json":       # {ok, read_only, data_age_s, commit}, public like the plain one
            return JSONResponse(_ro.healthz_json(_store.STORE, _head_commit()), headers={"Cache-Control": "no-store"})
        return PlainTextResponse(_healthz_body())
    if name == "healthz.json":
        return JSONResponse(_ro.healthz_json(_store.STORE, _head_commit()), headers={"Cache-Control": "no-store"})
    r = _page_at(request, name)
    if r is not None:
        return r
    if name not in _UI_PUBLIC:
        g = _ui_guard(request)
        if g is not None:
            return g
    if name == "manifest.webmanifest":
        return JSONResponse(_MANIFEST, media_type="application/manifest+json", headers={"Cache-Control": "no-cache"})
    if name == _FONT_PATH:                # /fonts/<the bundled font file>, versioned by ?v= like the icons (immutable when the version is current)
        p = _rmod.FONT_DIR / _rmod.FONT_FILE
        return _icon_file(request, p, "font/woff2") if p.is_file() else PlainTextResponse("not found", status_code=404)
    if name in _APP_ICONS:                # from the checkout, not <state>/site: they ship with the code that names them
        p = _APP_ICON_DIR / name
        return _icon_file(request, p, "image/png") if p.is_file() else PlainTextResponse("not found", status_code=404)
    if name == "board.md" and _ro.is_read_only():       # standby: from the in-memory render (_ro_board), no file
        from starlette.concurrency import run_in_threadpool
        r = await run_in_threadpool(_ro_board)
        if not r:
            return PlainTextResponse("board not rendered yet", status_code=503)
        return PlainTextResponse(r["full"], media_type="text/markdown")
    if name == "receivers.json":          # anchor-hub's live receiver checks, read on each request (no render, no git)
        return _receivers_response()
    if name == "board.md":
        md = _cfg.path("paths", "markdown")
        return FileResponse(str(md), media_type="text/markdown") if md.exists() else PlainTextResponse("board.md not rendered yet", status_code=503)
    if "/" in name or name.startswith(".") or not name:
        return PlainTextResponse("not found", status_code=404)
    p = _SITE_DIR / name
    if p.is_file() and p.suffix in _SITE_TYPES:
        if name == "favicon.svg":         # linked with its version like the app icons (render.py icon_href)
            return _icon_file(request, p, _SITE_TYPES[p.suffix])
        return FileResponse(str(p), media_type=_SITE_TYPES[p.suffix])
    return PlainTextResponse("not found", status_code=404)






# ----------------------------------------------------------------------------- the access log keeps no sign-in secrets
# uvicorn's access log records the request path with its query string. Three parameters carry a one-time sign-in value that
# does not belong in the journal: `code` (the OAuth authorization code on /auth/callback and /ui/callback), `state` (the
# OAuth state on /authorize and the callbacks) and `txn_id` (the consent transaction on the consent page). Each is single-use
# and short-lived, but the value of such a parameter is logged as `[redacted]` on every route; the path and the other
# parameters stay readable.
_REDACTED_PARAMS = frozenset({"code", "state", "txn_id"})


class _RedactCodes(logging.Filter):
    """uvicorn logs `'%s - "%s %s HTTP/%s" %d'` with args (client, method, path?query, http_version, status)."""
    def filter(self, record: logging.LogRecord) -> bool:
        a = record.args
        if isinstance(a, tuple) and len(a) == 5 and isinstance(a[2], str) and "?" in a[2]:
            path, _, query = a[2].partition("?")
            parts = query.split("&")
            if any(part.partition("=")[0] in _REDACTED_PARAMS for part in parts):
                query = "&".join(part.partition("=")[0] + "=[redacted]" if part.partition("=")[0] in _REDACTED_PARAMS else part
                                 for part in parts)
                record.args = (a[0], a[1], f"{path}?{query}", a[3], a[4])
        return True                                  # never drop a line, only rewrite it


# Installed at import, before uvicorn is configured: its dictConfig replaces the logger's handlers but keeps its filters.
logging.getLogger("uvicorn.access").addFilter(_RedactCodes())


def _on_hup() -> None:
    """SIGHUP (`systemctl --user reload stackshot.service`, which stackshot-reload.path runs when the config file changes): re-read
    stackshot.toml. A valid file is live at once and the board is published once; a broken one is logged and the running config
    kept; a RESTART_ONLY key is logged and waits for the restart (config.reload says which)."""
    changed = _cfg.reload()
    if changed is None:
        print("config reload: failed, nothing changed", file=sys.stderr, flush=True)
        return
    print(f"config reload: {', '.join(changed) if changed else 'no live setting changed'}"
          + (f"; waiting for a restart: {', '.join(_cfg.PENDING)}" if _cfg.PENDING else ""), file=sys.stderr, flush=True)
    if _ro.is_read_only():                  # the config is re-read; a standby copy has no stall pause to check and publishes nothing
        return
    try:
        _stall_pause_reload()
        _stall_pause_check()                                  # a pause of the stall pass read by this reload begins its clock now (the start line); the warning with its end is config.reload's own, once (config.notes carries stall_notes)
    except Exception as e:  # noqa: BLE001
        print(f"config reload: stall pause not checked: {e.__class__.__name__}: {e}", file=sys.stderr, flush=True)
    try:
        if not _watch.holding():            # a setting that feeds the reading ([waiting] dated_wait_min_hours, [instance] timezone) may have moved what the board shows: the stored phase follows now, not at the next minute
            _phase_sweep()                  # the publish below is this reload's own
    except Exception as e:  # noqa: BLE001
        print(f"config reload: phase sweep failed: {e.__class__.__name__}: {e}", file=sys.stderr, flush=True)
    _publish()


async def _serve() -> None:
    """mcp.run's own loop, with the reload signal on it."""
    import asyncio
    asyncio.get_running_loop().add_signal_handler(signal.SIGHUP, _on_hup)
    if _EARLY_HUP:
        _on_hup()
    s = _cfg.CFG["server"]
    await mcp.run_async(transport="http", host=s["host"], port=int(s["port"]), path=s["path"], show_banner=False,
                        **({"sockets": [_LISTEN]} if _LISTEN is not None else {}))   # the socket bound before the passes


def _start_background() -> list[str]:
    """The start-time passes and the background threads, in the order they have always run; → the names of the threads started.
    on a warm standby copy (STACKSHOT_READ_ONLY=1) nothing here runs and nothing starts: no record of the tools' text, no project-id
    stamp, no roles.json, no migration or wake pass (each writes items), no runner, no publish loop, no router, no page-debt call, no runners
    rebuild, no search index, no GitHub mirror (each acts outward or writes). The web UI and the MCP read tools are all a standby serves."""
    if _ro.is_read_only():
        print("stackshot: read-only standby copy (STACKSHOT_READ_ONLY): no start-time passes, no background threads; writes go to the live board", file=sys.stderr, flush=True)
        return []
    try:
        print(_wc.record(_paths.ROOT / "tests" / "tool_text.snapshot.json"), file=sys.stderr, flush=True)     # a start is a release; a change in the tools' text since the last one becomes the brief's what-changed line
    except Exception as e:
        print(f"what changed: not recorded: {e.__class__.__name__}: {e}", file=sys.stderr, flush=True)
    try:
        _prj.stamp_registry()               # phase A: the one-time backfill, every page of the registry carries its project id from the first second (minted once, never changed)
    except Exception as e:
        print(f"project ids: {e}", file=sys.stderr, flush=True)
    _roles_sync_safe()                      # roles.json is current from the first second, before any publish (and projects.json beside it)
    _stall_pause_reload()
    _stall_pause_check()                    # a pause of the stall pass read at the start begins its clock now (or keeps the one in <state>/stall_pause.json) and logs its end time
    for _n in _cfg.notes():                 # a setting missing from the one-file config that changes behaviour silently (the page rules off): a pause of the stall pass, with its end
        print(f"config: {_n}", file=sys.stderr, flush=True)
    _wait_alias_check()                     # one warning when [model] wait_alias_until is missing: the code's default end of the alias window stands
    try:
        if _migrate_holds():                # status on_hold → open + metadata.hold, before the first publish and the runner
            _publish()
    except Exception as e:
        print(f"hold migration failed: {e}", file=sys.stderr, flush=True)
    try:
        if _migrate_needs():                # needs a list, the linked agent (metadata.agent) in it; idempotent, so every start runs it
            _publish()
    except Exception as e:
        print(f"needs migration failed: {e}", file=sys.stderr, flush=True)
    try:
        if _session_ids_pass():             # step B: a requested move to permanent session ids (or its rollback), under the item lock, before the first publish
            _publish()
    except Exception as e:
        print(f"session ids pass failed: {e}", file=sys.stderr, flush=True)
    try:
        if _migrate_owner_mover():         # an item that waits on him has him as mover, his answered hand-offs are ended; idempotent, so every start runs it
            _publish()
    except Exception as e:
        print(f"mover migration failed: {e}", file=sys.stderr, flush=True)
    try:
        if _retire_rank_pass():             # ranks are retired: an open item's rank and a rank-only queued state are cleared, clocks unchanged; idempotent, so every start runs it
            _publish()
    except Exception as e:
        print(f"rank retirement pass failed: {e}", file=sys.stderr, flush=True)
    try:
        if [r for r in _mover_backfill_pass() if r["mover"]]:     # D1: a live item with no mover gets the project's builder, else its -main agent, never its creator; idempotent
            _publish()
    except Exception as e:
        print(f"mover backfill pass failed: {e}", file=sys.stderr, flush=True)
    try:
        if _handoff_repair_pass():          # an open hand-off record that names someone but the item's mover is ended into its history; idempotent, and before the wake pass and any thread
            _publish()
    except Exception as e:
        print(f"hand-off record repair failed: {e}", file=sys.stderr, flush=True)
    try:
        if _close_marks_pass():             # the closed items still showing an open step get them marked (done / dropped by outcome); idempotent, so every start runs it
            _publish()
    except Exception as e:
        print(f"close marks pass failed: {e}", file=sys.stderr, flush=True)
    try:
        if _wake_pass():                    # items whose wake passed while the server was down are open before the first publish
            _publish()
    except Exception as e:
        print(f"wake pass failed: {e}", file=sys.stderr, flush=True)
    try:
        _phase_tick()                       # a stored phase the down time left behind (a wait that ended, a deploy that changed the reading) is true before the first publish; the runner's first sweep is a minute away
    except Exception as e:
        print(f"phase sweep failed: {e}", file=sys.stderr, flush=True)
    print(f"stackshot: minute set: runner (one thread, one lock, paced rounds every {_minute.PACE:g} s)", file=sys.stderr, flush=True)
    if not _RUNNER:                         # a second start in the same process reuses the runner it has (start() is a no-op while its thread lives): never a second one, never an overwritten one
        _RUNNER[:] = [_make_runner()]
    _RUNNER[0].start()                      # the watchers' and anchor passes at their minute, the settle events, hand-off, answers and the fleet's clocks, in that order (runner.py)
    # The timer publish starts here with the runner, never at import: a test that imported the module
    # fired a publish at a 10-min mark and rebuilt its fixture registry.
    threading.Thread(target=_publish_loop, daemon=True).start()
    threading.Thread(target=_runner_watchdog_loop, name="runner-watchdog", daemon=True).start()   # the runner's watchdog: a look a minute, in a thread of its own (a stuck publish never silences it)
    threading.Thread(target=_router_live.loop, daemon=True).start()   # the router's ticks (a call takes minutes), in a thread of their own
    _runners.PERSIST = True             # the last runners snapshot is kept in a file under the state dir, and taken back here: the Runners pages draw it at once after a restart
    _runners.restore()
    _runners.AUTOSTART = True           # the side panel's Runners section may start its one background rebuild (runners.peek; [runners] panel = false stops it); never at import, so a test that renders the board makes no GitHub call
    _runners.ON_CHANGE = _publish_if_idle   # …and when that rebuild ends with other counts, the debounced publish (5 s) refreshes the home that is kept (False while a publish is running: runners.py asks again every 10 s for 2 min); one per panel_refresh_s
    threading.Thread(target=_search.loop, daemon=True).start()      # step 3: the search index's first build and its passes after a save, in a thread of its own
    threading.Thread(target=_gh.worker_loop, daemon=True).start()   # the GitHub mirror's worker; it idles while [github] sync is off (the default), so a reload can turn the mirror on
    threading.Thread(target=_gh.comments_loop, daemon=True).start() # phase 3: the reader of the owner's comments on the issues, beside the worker; idles the same way
    return ["runner", "publish", "watchdog", "router", "search", "ghsync-worker", "ghsync-comments"]


if __name__ == "__main__":
    _start_background()
    import anyio
    anyio.run(_serve)                   # = mcp.run(transport="http", …), plus the SIGHUP handler on its loop
